function logout() {
            layui.use(['layer'], function () {
                var layer = layui.layer;
                layer.confirm('确定要退出登录吗？', {
                    btn: ['确定', '取消']
                }, function () {
                    window.location.href = '/logout';
                });
            });
        }

var _xunStat = _xunStat || {};
